'use strict';
const $=id=>document.getElementById(id),runs=window.META_RSI_RESULTS,reduceMotion=matchMedia('(prefers-reduced-motion: reduce)').matches;
let key='mini',frame=0,selected=null,exported=null,filename=null,timer=null,frames=[],autoStarted=false,fullChartRange=false;
const run=()=>runs[key],pct=v=>(v*100).toFixed(2)+'%',esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function makeFrames(d){const out=[{round:0,phase:'scored'}];for(let r=1;r<=d.total_rounds;r++){out.push({round:r,phase:'generated'});if(r<=d.completed_rounds)out.push({round:r,phase:'scored'})}return out}
const current=()=>frames[frame];
function visibleNodes(){const f=current();return run().nodes.filter(n=>n.round<=f.round)}
function visibleScore(n){return n.score!==null&&(n.round<current().round||current().phase==='scored')?n.score:null}
function inBeam(n){if(!run().beam_by_round)return n.accepted;const f=current(),r=f.phase==='scored'?f.round:Math.max(0,f.round-1);return r===0?n.round===0:(run().beam_by_round[String(r)]||[]).includes(n.id)}
function bestVisible(){return visibleNodes().reduce((best,n)=>{const v=visibleScore(n);return v!==null&&v>best.score?{score:v,node:n}:best},{score:run().baseline,node:run().nodes[0]})}
function config(){return {harness:$('harness').value,model:$('model').value,method:$('method').value,config:{rounds:Number($('rounds').value),[$('method').value==='TreeRSI'?'branching_factor':$('method').value==='MetaHarness'?'population_size':'candidates']:Number($('candidates').value),seed:Number($('seed').value)},dataset:filename,execution:'not_started'}}
function exportPreview(){const n=run().nodes.find(n=>n.id===exported)||run().nodes[0];$('export-code').textContent=JSON.stringify({product:'meta-rsi',harness:run().harness,model:run().model,method:run().method,node:n.label,snapshot:n.id.slice(0,16)+'…',accuracy:n.score,files:n.file_count,source:'server '+run().server},null,2);$('export-node').textContent='✓ '+n.label+' · '+(n.score===null?'尚无评分':pct(n.score));$('download-harness').disabled=!n.artifact}
function spark(d,w=400,h=65){const min=d.baseline-.025,max=Math.max(...d.scores)+.025,x=i=>8+i*(w-16)/(d.scores.length-1),y=v=>h-5-(v-min)/(max-min)*(h-10);let path=`M${x(0)} ${y(d.scores[0])}`;d.scores.slice(1).forEach((v,i)=>path+=`H${x(i+1)}V${y(v)}`);return `<svg viewBox="0 0 ${w} ${h}" aria-hidden="true"><path d="${path}" fill="none"/></svg>`}
function hero(){const d=runs.mini,s=d.scores,x=i=>20+i*38.3,y=v=>175-(v-.70)*580;let path=`M20 ${y(s[0])}`;s.slice(1).forEach((v,i)=>path+=`H${x(i+1)}V${y(v)}`);$('hero-chart').innerHTML=`<defs><linearGradient id="hero-fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#a698ff" stop-opacity=".25"/><stop offset="1" stop-color="#a698ff" stop-opacity="0"/></linearGradient></defs><path d="M20 40H480M20 95H480M20 150H480" stroke="#303246" stroke-dasharray="3 6"/><path d="${path}V185H20Z" fill="url(#hero-fill)"/><path class="hero-line" d="${path}" fill="none" stroke="#b3a5ff" stroke-width="3"/><path d="M20 ${y(s[0])}H480" stroke="#7f8ca8" stroke-dasharray="4 6"/><circle class="endpoint" cx="480" cy="${y(s.at(-1))}" r="5" fill="#91e5e0"/><text x="20" y="205" fill="#8f93ad" font-size="11">BASELINE 73.33%</text><text x="402" y="205" fill="#8f93ad" font-size="11">12 ROUNDS</text>`;for(const k of Object.keys(runs))$(k+'-spark').innerHTML=spark(runs[k])}
function chartBounds(){const d=run();return fullChartRange?{low:0,high:1,step:.1}:{low:Math.max(0,Math.floor((d.baseline-.025)*20)/20),high:Math.min(1,Math.ceil((Math.max(d.baseline,...d.scores)+.025)*20)/20),step:.05}}
function chart(){const d=run(),f=current(),left=65,right=1040,{low,high,step}=chartBounds(),x=r=>left+r*(right-left)/d.total_rounds,y=v=>210-(v-low)/(high-low)*185;
$('chart-range').textContent=fullChartRange?'聚焦提升':'完整范围';$('chart-range').setAttribute('aria-pressed',fullChartRange);$('chart-range-note').textContent=`纵轴 ${Math.round(low*100)}–${Math.round(high*100)}% · ${fullChartRange?'全部分数':'聚焦 baseline 与历史最优'}`;
let html='';for(let v=low;v<=high+.001;v+=step)html+=`<path d="M${left} ${y(v)}H${right}" stroke="#292d42" stroke-dasharray="3 7"/><text x="13" y="${y(v)+4}" fill="#8c93ac" font-size="12">${Math.round(v*100)}%</text>`;
for(let r=0;r<=d.total_rounds;r++)html+=`<text x="${x(r)}" y="240" fill="${r===f.round?'#c7bbff':'#727991'}" text-anchor="middle" font-size="12">${r}</text>`;
html+=`<path d="M${left} ${y(d.baseline)}H${right}" stroke="#71849c" stroke-dasharray="6 6"/><path d="M${x(f.round)} 15V215" stroke="#a393e3" opacity=".3"/>`;
let best=d.baseline,path=`M${left} ${y(best)}`;for(let r=1;r<=f.round;r++){const ns=d.nodes.filter(n=>n.round===r);for(const n of ns){const v=visibleScore(n);if(v!==null)best=Math.max(best,v)}path+=`H${x(r)}V${y(best)}`}
html+=`<path d="${path}" stroke="#b6a6ff" stroke-width="3" fill="none" stroke-linejoin="round"/>`;
let clipped=0;
for(const n of visibleNodes()){const v=visibleScore(n);if(v===null)continue;const count=d.nodes.filter(v=>v.round===n.round).length,cx=x(n.round)+(n.round?((n.variant-1)-(count-1)/2)*8:0),outside=v<low,cy=outside?216:y(v);if(outside)clipped++;
const shape=outside?`<path d="M${cx-5} ${cy-4}L${cx+5} ${cy-4}L${cx} ${cy+3}Z" fill="#b39bce" stroke="${selected===n.id?'#fff':'#b39bce'}"/>`:`<circle cx="${cx}" cy="${cy}" r="${selected===n.id?6:4}" fill="${inBeam(n)?'#90e2dc':'#4d526b'}" stroke="${selected===n.id?'#fff':'#a7a0c9'}" stroke-width="1.5"/>`;
html+=`<g class="chart-point${outside?' chart-outlier':''}" data-node="${n.id}" tabindex="0" role="button" aria-label="${esc(n.label)} ${pct(v)}${outside?'，低于当前纵轴范围':''}"><circle cx="${cx}" cy="${cy}" r="10" fill="transparent"/>${shape}<title>${n.label} · ${pct(v)}${outside?'（低于当前纵轴范围）':''}</title></g>`}
$('chart-outlier-note').hidden=clipped===0;$('chart-outlier-note').textContent=`▼ ${clipped} 个候选低于 ${Math.round(low*100)}%，点击标记查看真实分数，或切换完整范围。`;
$('score-chart').innerHTML=html;document.querySelectorAll('.chart-point').forEach(el=>{const select=()=>{selected=el.dataset.node;drawTree();detail();chart()};el.onclick=select;el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select()}}});const bestNow=bestVisible();$('baseline-score').textContent=pct(d.baseline);$('best-score').textContent=pct(bestNow.score);$('gain-score').textContent='+'+((bestNow.score-d.baseline)*100).toFixed(2)+' pp'}
function drawTree(){const visible=visibleNodes(),f=current(),width=Math.max(590,(f.round+1)*170+50),rows=Math.max(...Array.from({length:f.round+1},(_,r)=>visible.filter(n=>n.round===r).length)),height=Math.max(285,rows*115+55),pos=n=>({x:80+n.round*170,y:n.round===0?70:65+(n.variant-1)*115});let html=`<svg width="${width}" height="${height-30}" aria-hidden="true" style="height:${height-30}px">`;for(const n of visible){if(!n.parent)continue;const parent=visible.find(p=>p.id===n.parent);if(!parent)continue;const a=pos(parent),b=pos(n);html+=`<path class="tree-edge" d="M${a.x} ${a.y} C${a.x+90} ${a.y},${b.x-90} ${b.y},${b.x} ${b.y}" fill="none" stroke="${inBeam(n)&&visibleScore(n)!==null?'#8273c4':'#34394f'}" stroke-width="1.5"/>`}html+='</svg>';
$('tree').style.width=width+'px';$('tree').style.height=height+'px';$('tree').innerHTML=html;
for(let r=0;r<=f.round;r++){const label=document.createElement('span');label.className='tree-round-label';label.style.left=(80+r*170)+'px';label.textContent=r===0?'BASELINE':'ROUND '+String(r).padStart(2,'0');$('tree').appendChild(label);if(r>0&&!visible.some(n=>n.round===r)){const empty=document.createElement('span');empty.className='empty-round';empty.style.left=(80+r*170)+'px';empty.textContent='无有效候选';$('tree').appendChild(empty)}}
for(const n of visible){const b=document.createElement('button'),p=pos(n),v=visibleScore(n);b.type='button';b.className='node'+(inBeam(n)&&v!==null?' accepted':'')+(n.id===selected?' selected':'')+(n.round===f.round?' newly-added':'');b.style.left=p.x+'px';b.style.top=p.y+'px';b.setAttribute('aria-pressed',n.id===selected);b.innerHTML=`<small>${n.label} <span>${v===null?'◌':inBeam(n)?'●':'○'}</span></small><strong>${v===null?'等待评估':pct(v)}</strong><em>${esc(n.round===0?'原始基线':n.title)}</em>`;b.onclick=()=>{selected=n.id;drawTree();detail();chart()};$('tree').appendChild(b)}$('node-count').textContent=visible.length+' NODES';$('tree-legend').innerHTML=run().beam_by_round?'● 当前束选中 <i>○ 其他候选 / 待评估</i>':'● 已采纳 <i>○ 未采纳 / 待评估</i>';
$('beam-summary').hidden=!run().beam_by_round;if(run().beam_by_round){const beam=visible.filter(n=>inBeam(n));$('beam-summary').textContent='当前搜索束：'+beam.map(n=>n.label).join(' / ')+' · 拖动查看全部分支'}
}
function detail(){const n=run().nodes.find(n=>n.id===selected)||run().nodes[0],v=visibleScore(n);$('node-id').textContent=n.label+' / '+n.id.slice(0,10);$('node-title').textContent=n.title;$('node-score').textContent=v===null?'待评估':pct(v);$('node-description').textContent=n.round===0?`${run().tasks} 个进化任务，每题重复 ${run().repeats} 次；正式评估不包含 smoke 预检查。`:`父节点 ${n.parent.slice(0,12)} · ${n.paths.length} 个改动路径`;
$('decision').textContent=v===null?'候选已生成 · 完整分数尚未揭晓':n.round===0?'BASELINE · 进化起点':run().beam_by_round?(inBeam(n)?'✓ 已进入搜索树 · 当前搜索束选中':'○ 已进入搜索树 · 当前搜索束未选中'):(n.accepted?'✓ 原生选择器采纳':'○ 原生选择器未采纳');$('decision').classList.toggle('is-accepted',v!==null&&inBeam(n));
$('node-changes').replaceChildren(...(n.paths.length?n.paths:['初始 Harness · '+n.file_count+' 个资源文件']).map(p=>{const li=document.createElement('li');li.textContent=p;return li}));$('hypothesis').textContent=n.changes.map(c=>c.hypothesis).filter(Boolean).join('\n\n')||'基线未发生进化修改。';$('node-diff').textContent=n.diff||'此记录未提供完整代码差异。';if(v!==null&&n.reason)$('hypothesis').textContent+='\n\n原生决定：'+n.reason;if(v!==null&&n.error_trials)$('hypothesis').textContent+=`\n正式评估执行错误：${n.error_trials} / ${n.n_trials}，原始分数保留。`;$('select-node').disabled=v===null||!n.artifact}
function render(scroll=false){const d=run(),f=current();$('timeline').value=f.round;$('round-label').textContent=`ROUND ${String(f.round).padStart(2,'0')} / ${d.total_rounds}`;let text=f.round===0?'基线就绪 · 等待第一轮候选':f.phase==='generated'?`第 ${f.round} 轮 · 候选生成，等待评估结果`:`第 ${f.round} 轮 · 评估与选择完成`;
if(f.round>0&&!d.nodes.some(n=>n.round===f.round))text=`第 ${f.round} 轮 · 未生成有效候选，保留上一轮结果`;
if(frame===frames.length-1&&f.round>d.completed_rounds)text=`第 ${f.round} 轮 · 已生成候选，原始记录中尚无完整评分`;
$('frame-status').textContent=text;$('prev').disabled=f.round===0;$('next').disabled=frame===frames.length-1;chart();drawTree();detail();if(scroll){const panel=document.querySelector('.tree-scroll');panel.scrollTo({left:Math.max(0,f.round*170-panel.clientWidth/2),top:0,behavior:reduceMotion?'instant':'smooth'})}}
function pause(){clearTimeout(timer);timer=null;$('play').textContent='▶ 播放进化';$('play').setAttribute('aria-pressed','false')}
function schedule(){timer=setTimeout(()=>{if(frame>=frames.length-1){pause();$('play').textContent='↺ 再看一次';return}frame++;const newest=visibleNodes().filter(n=>n.round===current().round);if(newest.length)selected=newest.at(-1).id;render(true);schedule()},Number($('speed').value))}
function play(){if(timer){pause();return}if(frame===frames.length-1){frame=0;selected=run().nodes[0].id;render(true)}autoStarted=true;$('play').textContent='Ⅱ 暂停回放';$('play').setAttribute('aria-pressed','true');schedule()}
function goRound(round){pause();const idx=frames.findLastIndex(f=>f.round===round);frame=Math.max(0,idx);const candidates=visibleNodes().filter(n=>n.round===round);selected=candidates.at(-1)?.id||bestVisible().node.id;render(true)}
function activate(k){pause();key=k;frames=makeFrames(run());frame=0;selected=run().nodes[0].id;exported=run().best_id;$('harness').value=run().harness;$('method').value=run().method;$('method').dispatchEvent(new Event('change'));$('timeline').max=run().total_rounds;$('timeline-end').textContent='ROUND '+run().total_rounds;$('run-label').textContent=run().harness+' / DeepSeek / '+run().method;$('source-note').textContent=`来源：${run().server} · ${run().dataset} · ${run().tasks} 题 × ${run().repeats} 次 · 采集于 ${new Date(run().retrieved_at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false})}（北京时间）。记录已完成 ${run().completed_rounds} 轮${run().total_rounds>run().completed_rounds?'，后续候选尚未完成评估':''}。此处为历史记录回放，不代表实验正在运行；进化集成绩不等于独立测试成绩。`;
document.querySelectorAll('[data-case]').forEach(b=>{b.classList.toggle('active',b.dataset.case===k);b.setAttribute('aria-pressed',b.dataset.case===k)});render();exportPreview()}
function download(name,data){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
document.querySelectorAll('[data-case]').forEach(b=>b.onclick=()=>{activate(b.dataset.case);autoStarted=true;$('evolution').scrollIntoView({behavior:reduceMotion?'instant':'smooth'});play()});$('play').onclick=play;$('prev').onclick=()=>goRound(Math.max(0,current().round-1));$('next').onclick=()=>goRound(Math.min(run().total_rounds,current().round+1));$('reset').onclick=()=>{pause();frame=0;selected=run().nodes[0].id;render(true)};$('timeline').oninput=e=>goRound(Number(e.target.value));$('speed').onchange=()=>{if(timer){clearTimeout(timer);schedule()}};
$('dataset').onchange=e=>{filename=e.target.files[0]?.name||null;$('file-status').textContent=filename?'已选择：'+filename+' · 文件未上传':'JSON / JSONL / CSV / TXT · 仅在本地选择'};$('method').onchange=()=>{$('param-label').firstChild.textContent=$('method').value==='TreeRSI'?'分支数量 ':$('method').value==='MetaHarness'?'种群大小 ':'候选数量 '};$('config-form').onsubmit=e=>{e.preventDefault();$('config-status').textContent='新任务启动服务尚未接入，暂时无法开始进化。你可以在下方查看已有实验记录，或在导出区下载配置。'};$('select-node').onclick=()=>{exported=selected;exportPreview();$('export').scrollIntoView({behavior:reduceMotion?'instant':'smooth'})};$('download-config').onclick=()=>{if($('config-form').reportValidity())download('meta-rsi.config.json',config())};$('download-harness').onclick=()=>{const n=run().nodes.find(n=>n.id===exported);if(!n?.artifact)return;const a=document.createElement('a');a.href=n.artifact;a.download='meta-rsi-'+key+'-'+n.label.replaceAll(' · ','-')+'.zip';a.click()};document.addEventListener('visibilitychange',()=>{if(document.hidden)pause()});
function renderTests(mode='current'){for(const name of ['current','original','revised']){const button=$('test-'+name);button.classList.toggle('active',mode===name);button.setAttribute('aria-pressed',mode===name)}$('test-table-body').innerHTML=Object.entries(runs).map(([key,d])=>{const t=d.test_results;if(!t)return '';const revised=mode==='revised'||(mode==='current'&&['claude','tree'].includes(key));const a=revised&&t.revised?t.revised:t.original;return `<tr><th scope="row"><b>${esc(d.harness)}</b><span>${esc(d.method)} · SERVER .${d.server.split('.').at(-1)}</span></th><td>${pct(a.baseline_passed/t.tasks)}<small>${a.baseline_passed} / ${t.tasks}</small></td><td class="test-best">${pct(a.best_passed/t.tasks)}<small>${a.best_passed} / ${t.tasks}</small></td><td class="test-gain">+${((a.best_passed-a.baseline_passed)/t.tasks*100).toFixed(2)} pp</td></tr>`}).join('');$('test-caveat').textContent=mode==='current'?'当前展示：Claude Code 使用环境修复后的 39/59 → 41/59；TreeRSI 使用重测后的 40/59 → 47/59；MiniAgent / RRSI 保留首次测试。可切换查看首次记录或包含重测的汇总。不同评估口径不作为严格控制变量的方法排名。':mode==='revised'?'重测口径不同：Claude Code 仅替换已确认的环境故障；TreeRSI 使用诊断重测替换汇总；MiniAgent / RRSI 保留首次结果。请结合首次测试一起阅读，不能视为统一重测条件下的排名。':'每个单元格显示正确率与通过任务数。各实验基线与评估环境不同，结果用于呈现各自的进化前后变化，不作为严格控制变量的方法排名。';}
function testEvidence(){$('test-evidence-content').replaceChildren(...Object.entries(runs).filter(([,d])=>d.test_results).map(([key,d])=>{const t=d.test_results,el=document.createElement('section');const h=document.createElement('h4');h.textContent=d.harness+' / '+d.method;const p=document.createElement('p');p.textContent=t.note;const code=document.createElement('pre');code.textContent=`Baseline: ${t.baseline_id}\nEvolved: ${t.best_id}\n`+t.sources.map(s=>s.path+'\nSHA-256: '+s.sha256).join('\n');el.append(h,p,code);return el}))}
$('chart-range').onclick=()=>{fullChartRange=!fullChartRange;chart()};
$('test-current').onclick=()=>renderTests('current');$('test-original').onclick=()=>renderTests('original');$('test-revised').onclick=()=>renderTests('revised');renderTests();testEvidence();
hero();activate('mini');
if('IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('revealed');if(e.target.id==='evolution'&&!autoStarted&&!reduceMotion){autoStarted=true;play()}observer.unobserve(e.target)}}),{threshold:.12});document.querySelectorAll('.section,.export-section,.closing').forEach(el=>{el.classList.add('reveal');observer.observe(el)})}
